// OnAir Web 3.9: the panel schema of every mode (core/src/results/web_schema*.cpp, generated by tools/gen_web_schema.py).
//  1. every row of the mode table (as generated into webModeRows) has a schema, except the ones listed as having no telemetry block;
//  2. for every standard with a schema, the exporter writes valid JSON from a default RxTelemetry, and the schema itself is valid JSON
//     with the required keys; every field of the schema appears in the exported object;
//  3. the value writers: UTF-8 cleaning, NaN -> null, constellation subsampling, tables with positions get a map hint, pictures become a
//     PNG data URL (decoded back and checked), the size cap, and the mode list JSON.
#include "dect2/results/web_schema.h"
#include "dect2/t2/t2rx.h"
#include "../common/test_util.h"
#include <cmath>
#include <cstring>
#include <set>
#include <string>

using namespace dect2;
using namespace dect2::webschema;

// ---------------------------------------------------------------- a small strict JSON checker (no values kept): counts nodes
struct JsonCheck {
    const std::string& s;
    size_t i = 0;
    size_t nodes = 0;
    std::string err;
    explicit JsonCheck(const std::string& str) : s(str) {}
    void ws() { while (i < s.size() && (s[i] == ' ' || s[i] == '\n' || s[i] == '\r' || s[i] == '\t')) i++; }
    bool fail(const char* w) { if (err.empty()) err = std::string(w) + " at " + std::to_string(i); return false; }
    bool string() {
        if (s[i] != '"') return fail("string");
        i++;
        while (i < s.size()) {
            const unsigned char c = (unsigned char)s[i];
            if (c == '"') { i++; return true; }
            if (c == '\\') { i++; if (i >= s.size()) return fail("escape"); const char e = s[i]; if (e == 'u') { for (int k = 0; k < 4; k++) { i++; if (i >= s.size() || !isxdigit((unsigned char)s[i])) return fail("\\u"); } } else if (!strchr("\"\\/bfnrt", e)) return fail("escape"); i++; continue; }
            if (c < 0x20) return fail("control char");
            i++;
        }
        return fail("unterminated string");
    }
    bool value(int depth) {
        if (depth > 32) return fail("depth");
        nodes++;
        ws();
        if (i >= s.size()) return fail("eof");
        const char c = s[i];
        if (c == '{') {
            i++; ws();
            if (s[i] == '}') { i++; return true; }
            while (true) { ws(); if (!string()) return false; ws(); if (s[i] != ':') return fail("colon"); i++; if (!value(depth + 1)) return false; ws(); if (s[i] == ',') { i++; continue; } if (s[i] == '}') { i++; return true; } return fail("object"); }
        }
        if (c == '[') {
            i++; ws();
            if (s[i] == ']') { i++; return true; }
            while (true) { if (!value(depth + 1)) return false; ws(); if (s[i] == ',') { i++; continue; } if (s[i] == ']') { i++; return true; } return fail("array"); }
        }
        if (c == '"') return string();
        if (s.compare(i, 4, "true") == 0) { i += 4; return true; }
        if (s.compare(i, 5, "false") == 0) { i += 5; return true; }
        if (s.compare(i, 4, "null") == 0) { i += 4; return true; }
        if (c == '-' || (c >= '0' && c <= '9')) {
            const size_t st = i;
            if (s[i] == '-') i++;
            while (i < s.size() && (isdigit((unsigned char)s[i]) || s[i] == '.' || s[i] == 'e' || s[i] == 'E' || s[i] == '+' || s[i] == '-')) i++;
            if (i == st) return fail("number");
            return true;
        }
        return fail("value");
    }
    bool all() { const bool ok = value(0); ws(); if (ok && i != s.size()) return fail("trailing"); return ok; }
};
static bool validJson(const std::string& s, std::string* why = nullptr) { JsonCheck c(s); const bool ok = c.all(); if (why) *why = c.err; return ok; }

static std::string jsonKeys(const std::string& arr, std::set<std::string>& names) {
    // the "n" values of the top-level objects of a schema array (nested "f" schemas of rows and blocks are deeper)
    int depth = 0;
    bool inStr = false;
    for (size_t i = 0; i < arr.size(); i++) {
        const char c = arr[i];
        if (inStr) { if (c == '\\') i++; else if (c == '"') inStr = false; continue; }
        if (c == '"') {
            if (depth == 2 && arr.compare(i, 5, "\"n\":\"") == 0) { const size_t e = arr.find('"', i + 5); names.insert(arr.substr(i + 5, e - i - 5)); i = e; continue; }
            inStr = true;
        } else if (c == '[' || c == '{') depth++;
        else if (c == ']' || c == '}') depth--;
    }
    return "";
}

// a stored-deflate PNG back to pixels (enough for what pngStored writes)
static bool pngDecodeStored(const std::vector<uint8_t>& png, int& w, int& h, int& ch, std::vector<uint8_t>& px) {
    if (png.size() < 8 + 25 || memcmp(png.data(), "\x89PNG\r\n\x1a\n", 8) != 0) return false;
    size_t i = 8;
    std::vector<uint8_t> idat;
    while (i + 8 <= png.size()) {
        const uint32_t len = (png[i] << 24) | (png[i + 1] << 16) | (png[i + 2] << 8) | png[i + 3];
        const std::string type((const char*)&png[i + 4], 4);
        const uint8_t* d = &png[i + 8];
        if (type == "IHDR") { w = (d[0] << 24) | (d[1] << 16) | (d[2] << 8) | d[3]; h = (d[4] << 24) | (d[5] << 16) | (d[6] << 8) | d[7]; ch = d[9] == 0 ? 1 : d[9] == 2 ? 3 : 0; }
        else if (type == "IDAT") idat.insert(idat.end(), d, d + len);
        i += 12 + len;
    }
    if (!ch || idat.size() < 7) return false;
    size_t p = 2;
    std::vector<uint8_t> raw;
    while (p + 5 <= idat.size()) {
        const bool last = idat[p] & 1;
        const size_t n = idat[p + 1] | (idat[p + 2] << 8);
        p += 5;
        raw.insert(raw.end(), idat.begin() + p, idat.begin() + p + n);
        p += n;
        if (last) break;
    }
    const size_t stride = (size_t)w * ch;
    if (raw.size() != (stride + 1) * h) return false;
    px.clear();
    for (int y = 0; y < h; y++) { if (raw[y * (stride + 1)] != 0) return false; px.insert(px.end(), raw.begin() + y * (stride + 1) + 1, raw.begin() + (y + 1) * (stride + 1)); }
    return true;
}
static std::vector<uint8_t> b64decode(const std::string& s) {
    std::vector<uint8_t> o;
    int val = 0, bits = -8;
    for (char c : s) {
        int d;
        if (c >= 'A' && c <= 'Z') d = c - 'A'; else if (c >= 'a' && c <= 'z') d = c - 'a' + 26; else if (c >= '0' && c <= '9') d = c - '0' + 52; else if (c == '+') d = 62; else if (c == '/') d = 63; else break;
        val = (val << 6) | d; bits += 6;
        if (bits >= 0) { o.push_back((uint8_t)((val >> bits) & 0xFF)); bits -= 8; }
    }
    return o;
}

int main() {
    int fails = 0;
    // ---- 1. every mode row
    int n = 0, ng = 0;
    const WebModeRow* rows = webModeRows(n);
    webModeGroups(ng);
    CHECK(n >= 290, "the mode table has %d rows (expected 290 or more)", n);
    CHECK(ng >= 10, "%d groups", ng);
    int withSchema = 0;
    std::set<std::string> noSchema;
    for (int i = 0; i < n; i++) {
        const WebModeRow& r = rows[i];
        CHECK(r.name && *r.name, "row %d has a name", i);
        CHECK(r.group >= 0 && r.group < ng, "row %s: group %d", r.name, r.group);
        if (r.family >= 6) CHECK(r.engineStd == r.family + 2 && r.standard == r.family + 1, "row %s: family %d -> engine %d, standard %d", r.name, r.family, r.engineStd, r.standard);
        if (schemaJson(r.standard)) { withSchema++; CHECK(r.member && *r.member, "row %s has a schema but no member", r.name); }
        else noSchema.insert(r.name);
    }
    // the TV standards carry the common block + details (no own block); the rest without a block are known and listed in docs/WEB-SCHEMA-3.9.md
    static const char* const kKnownNoBlock[] = {"DVB", "TV (auto)", "ATSC", "ATSC 3.0", "ISDB-T", "DAB / DAB+", "FM", "Internet TV (IPTV)", "ASTERIX", "ISDB-TSB", "DVB-SH", "Mode Builder", "Plugins"};
    for (const std::string& name : noSchema) {
        bool known = false;
        for (const char* k : kKnownNoBlock) if (name == k) known = true;
        CHECK(known, "mode \"%s\" has no panel schema and is not on the known list", name.c_str());
    }
    printf("mode rows: %d, with a schema: %d, without: %d\n", n, withSchema, (int)noSchema.size());
    const int nKnown = (int)(sizeof kKnownNoBlock / sizeof *kKnownNoBlock);
    CHECK(withSchema >= n - nKnown, "at least all but the %d known rows have a schema (%d of %d)", nKnown, withSchema, n);

    // ---- 2. every standard: valid JSON from a default report; the schema is valid and its fields appear
    const std::vector<int> stds = schemaStandards();
    CHECK(stds.size() >= 240, "%zu standards with a schema", stds.size());
    size_t maxBytes = 0;
    int maxStd = -1;
    for (int sd : stds) {
        std::string why;
        const std::string sch = schemaJson(sd);
        CHECK(validJson(sch, &why), "schema %d (%s): %s", sd, schemaStruct(sd), why.c_str());
        CHECK(sch.size() > 2 && sch[0] == '[', "schema %d is an array", sd);
        RxTelemetry t;
        t.standard = sd;
        t.seq = 1;
        std::string out;
        CHECK(panelJson(t, out), "panelJson for standard %d", sd);
        CHECK(validJson(out, &why), "panel %d (%s): %s ... %.120s", sd, schemaStruct(sd), why.c_str(), out.c_str());
        CHECK(out.find("\"standard\":" + std::to_string(sd)) != std::string::npos, "panel %d says its standard", sd);
        CHECK(out.find("\"fields\":{") != std::string::npos, "panel %d has fields", sd);
        std::set<std::string> names;
        jsonKeys(sch, names);
        CHECK(!names.empty(), "schema %d has fields", sd);
        for (const std::string& nm : names) {
            if (nm == "image") continue;   // added by the exporter when the picture has data
            CHECK(out.find("\"" + nm + "\":") != std::string::npos, "panel %d: field %s of the schema is in the output", sd, nm.c_str());
        }
        if (out.size() > maxBytes) { maxBytes = out.size(); maxStd = sd; }
    }
    printf("largest default panel: standard %d (%s), %zu bytes\n", maxStd, maxStd >= 0 ? schemaStruct(maxStd) : "", maxBytes);
    CHECK(maxBytes < 64 * 1024, "a default panel stays under 64 KB (%zu)", maxBytes);
    {
        std::string why;
        const std::string all = allSchemasJson();
        CHECK(validJson(all, &why), "allSchemasJson: %s", why.c_str());
        CHECK(all.find("\"common\":[") != std::string::npos, "the common schema is in it");
        const std::string modes = webModesJson();
        CHECK(validJson(modes, &why), "webModesJson: %s", why.c_str());
        CHECK(modes.find("\"groups\":[") != std::string::npos && modes.find("\"modes\":[") != std::string::npos, "modes JSON shape");
        CHECK(validJson(commonSchemaJson(), &why), "common schema: %s", why.c_str());
    }
    // the TV standards: the common block only, fields {}
    {
        RxTelemetry t;
        t.standard = 0;
        std::string out;
        CHECK(!panelJson(t, out), "standard 0 has no own block");
        CHECK(validJson(out), "the TV panel is valid JSON");
        CHECK(out.find("\"fields\":{}") != std::string::npos, "the TV panel's fields are empty");
    }

    // ---- 3. the writers
    using namespace detail;
    {
        std::string s;
        vnum(s, NAN); CHECK(s == "null", "NaN -> null: %s", s.c_str());
        s.clear(); vnum(s, 3.0); CHECK(s == "3", "integer: %s", s.c_str());
        s.clear(); vnum(s, -0.5); CHECK(s == "-0.5", "fraction: %s", s.c_str());
        s.clear(); vnum(s, 1e20); CHECK(validJson(s) && s.find("e") != std::string::npos, "big number: %s", s.c_str());
        s.clear(); vstr(s, std::string("a\"b\\c\n\x01") + "\xC3\xA9" + "\xFF" + "\xE2\x82\xAC", 100);
        CHECK(validJson(s), "escaped string is valid: %s", s.c_str());
        CHECK(s.find("\\u0001") != std::string::npos && s.find("\xC3\xA9") != std::string::npos && s.find('?') != std::string::npos, "escapes, UTF-8 kept, bad byte replaced: %s", s.c_str());
        s.clear(); vstr(s, "\xE2\x82\xAC\xE2\x82\xAC", 4);
        CHECK(s == "\"\xE2\x82\xAC\"", "cut on a character boundary: %s", s.c_str());
        float iq[2000];
        for (int i = 0; i < 1000; i++) { iq[2 * i] = (float)i; iq[2 * i + 1] = -(float)i; }
        s.clear(); vconst(s, iq, 1000, 100);
        CHECK(validJson(s), "const JSON");
        size_t commas = 0; for (char c : s) if (c == ',') commas++;
        CHECK(commas + 1 <= 2 * 100 + 2 && commas + 1 >= 2 * 90, "const subsampled to about 100 points: %zu values", commas + 1);
        s.clear(); vconst(s, iq, 0, 100); CHECK(s == "[]", "empty const");
    }
    {   // a picture: grey 5x3 and RGB 4x2 round-trip through the PNG writer
        uint8_t g[15]; for (int i = 0; i < 15; i++) g[i] = (uint8_t)(i * 17);
        const std::vector<uint8_t> png = pngStored(g, 5, 3, 1);
        int w = 0, h = 0, ch = 0; std::vector<uint8_t> px;
        CHECK(pngDecodeStored(png, w, h, ch, px) && w == 5 && h == 3 && ch == 1 && px.size() == 15 && memcmp(px.data(), g, 15) == 0, "grey PNG round trip");
        uint8_t rgb[24]; for (int i = 0; i < 24; i++) rgb[i] = (uint8_t)(255 - i * 9);
        const std::vector<uint8_t> png2 = pngStored(rgb, 4, 2, 3);
        CHECK(pngDecodeStored(png2, w, h, ch, px) && w == 4 && h == 2 && ch == 3 && memcmp(px.data(), rgb, 24) == 0, "RGB PNG round trip");
        std::string s;
        vimage(s, g, 15, 5, 3);
        CHECK(s.compare(0, 23, "\"data:image/png;base64,") == 0 && s.back() == '"', "data URL: %.40s", s.c_str());
        const std::vector<uint8_t> back = b64decode(s.substr(23, s.size() - 24));
        CHECK(back == png, "the data URL carries the PNG");
        s.clear(); vimage(s, g, 14, 5, 3); CHECK(s == "null", "a size that is neither grey nor RGB -> null");
        // a wide picture is downscaled to 1024 columns
        std::vector<uint8_t> big((size_t)3000 * 4, 100);
        s.clear(); vimage(s, big.data(), big.size(), 3000, 4);
        const std::vector<uint8_t> bp = b64decode(s.substr(23, s.size() - 24));
        CHECK(pngDecodeStored(bp, w, h, ch, px) && w == 1000 && h == 2 && ch == 1 && px[0] == 100, "downscaled to %d x %d", w, h);
        CHECK(pngStored(nullptr, 1, 1, 1).empty() && pngStored(g, 0, 1, 1).empty() && pngStored(g, 1, 1, 2).empty(), "bad arguments -> empty");
    }
    {   // a mode with tables, positions and a map hint: ADS-B (standard 12)
        const char* sch = schemaJson(12);
        CHECK(sch && std::string(sch).find("\"n\":\"aircraft\",\"l\":\"Most recently heard first\",\"k\":\"table\",\"s\":\"dect2::AdsbAircraft\"") != std::string::npos, "ADS-B schema has the aircraft table with its label");
        CHECK(sch && std::string(sch).find("\"f\":[{\"n\":\"icao\"") != std::string::npos, "the table carries its columns' schema");
        CHECK(sch && std::string(sch).find("\"map\":{\"lat\":\"lat\",\"lon\":\"lon\"") != std::string::npos, "the aircraft table has a map hint: %.300s", sch ? strstr(sch, "aircraft") : "");
        CHECK(sch && std::string(sch).find("\"u\":\"dB\"") != std::string::npos, "units are parsed from names");
        RxTelemetry t;
        t.standard = 12;
        t.adsb.aircraftCount = 1;
        t.adsb.aircraft.resize(3);
        t.adsb.aircraft[0].lat = 54.7; t.adsb.aircraft[0].lon = 25.3;
        std::string out, why;
        CHECK(panelJson(t, out), "ADS-B panel");
        CHECK(validJson(out, &why), "ADS-B panel JSON: %s", why.c_str());
        CHECK(out.find("\"aircraft\":[{") != std::string::npos && out.find("\"lat\":54.7") != std::string::npos, "the aircraft rows are exported");
        // the row cap
        t.adsb.aircraft.resize(300);
        out.clear();
        panelJson(t, out, 4 << 20);   // 300 rows of this struct are over the default 256 KB cap: the cap is checked below
        size_t cnt = 0, p = 0;
        while ((p = out.find("\"icao\":", p)) != std::string::npos) { cnt++; p += 7; }
        CHECK(cnt == 200, "tables are capped at 200 rows (%zu, %zu bytes)", cnt, out.size());
        CHECK(validJson(out), "capped table is valid JSON");
        // the size cap
        out.clear();
        panelJson(t, out, 2000);
        CHECK(out.find("\"fields\":{\"truncated\":true}") != std::string::npos && validJson(out), "over the cap the own block is replaced");
    }
    {   // a constellation in the DVB-T2 block comes through rx_json, and in a mode block as "const"
        bool anyConst = false;
        for (int sd : stds) if (std::string(schemaJson(sd)).find("\"k\":\"const\"") != std::string::npos) anyConst = true;
        CHECK(anyConst, "at least one mode exports a constellation");
        bool anyImage = false, anyLines = false;
        for (int sd : stds) { const std::string s = schemaJson(sd); if (s.find("\"k\":\"image\"") != std::string::npos) anyImage = true; if (s.find("\"k\":\"lines\"") != std::string::npos) anyLines = true; }
        CHECK(anyImage, "at least one mode exports a picture (in a nested block's schema)");
        // FSQ inherits its block: the base's fields are exported
        CHECK(schemaJson(114) && std::string(schemaJson(114)).size() > 50, "FSQ (standard 114) has the fields of its base struct");
        CHECK(anyLines, "at least one mode exports text lines");
    }
    printf("web_schema: %s (%d failures)\n", fails ? "FAIL" : "ok", fails);
    return fails ? 1 : 0;
}
